mkdir -p migrations/down && cat > migrations/002_login_attempts.sql <<'EOF'
-- Counts login tries per key (account or IP) in a fixed window; shared by all servers.
create table login_attempts (
  key text primary key,
  n integer not null check (n >= 0),
  since timestamptz not null default now()
);
EOF
cat > migrations/down/002_login_attempts.sql <<'EOF'
drop table login_attempts;
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('import { pool } from "./db.ts";','import { pool } from "./db.ts";\nimport { hashPassword, verifyPassword } from "./passwords.ts";',1)
s=s.replace('''export function createApp() {''','''const LOGIN_WINDOW = "15 minutes";
const LOGIN_MAX_PER_EMAIL = 10;
const LOGIN_MAX_PER_IP = 50;

// Counts one try atomically (the window restarts once it has expired) and returns the count so far.
async function countAttempt(key: string): Promise<number> {
  const { rows } = await pool.query(
    `insert into login_attempts (key, n, since) values ($1, 1, now())
     on conflict (key) do update set
       n = case when login_attempts.since < now() - $2::interval then 1 else login_attempts.n + 1 end,
       since = case when login_attempts.since < now() - $2::interval then now() else login_attempts.since end
     returning n`,
    [key, LOGIN_WINDOW],
  );
  return rows[0].n;
}

// Used for unknown emails so they take as long as a real password check.
const dummyHash = await hashPassword("not-a-real-password");

export function createApp() {''',1)
s=s.replace('''  app.use(auth);
''','''  app.post("/login", async (req, res) => {
    const { email, password } = req.body ?? {};
    if (typeof email !== "string" || typeof password !== "string" || !email || !password || email.length > 320 || password.length > 1024) {
      return sendError(res, 400, "invalid_request", "email and password are required strings");
    }
    const emailCount = await countAttempt(`login:email:${email.toLowerCase()}`);
    const ipCount = await countAttempt(`login:ip:${req.ip ?? "unknown"}`);
    if (emailCount > LOGIN_MAX_PER_EMAIL || ipCount > LOGIN_MAX_PER_IP) {
      return sendError(res, 429, "too_many_attempts", "Try again later");
    }
    const { rows } = await pool.query("select api_token, password_hash from users where lower(email) = lower($1) limit 1", [email]);
    const ok = await verifyPassword(password, rows[0]?.password_hash ?? dummyHash);
    if (rows.length === 0 || !ok) return sendError(res, 401, "invalid_credentials", "Invalid email or password");
    res.json({ token: rows[0].api_token });
  });

  app.use(auth);
''',1)
open(p,'w').write(s)

p='postman/shop-api.postman_collection.json'
s=open(p).read()
s=s.replace('''    { "name": "Me",''','''    {
      "name": "Login",
      "request": {
        "method": "POST",
        "auth": { "type": "noauth" },
        "header": [{ "key": "Content-Type", "value": "application/json" }],
        "body": { "mode": "raw", "raw": "{\\n  \\"email\\": \\"alice@example.com\\",\\n  \\"password\\": \\"alice-password\\"\\n}" },
        "url": "{{baseUrl}}/login"
      }
    },
    { "name": "Me",''',1)
open(p,'w').write(s)

p='test/app.test.ts'
s=open(p).read()
s+='''
const login = (body: unknown) =>
  fetch(`${base}/login`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });

test("/login returns the api token without a token", async () => {
  const res = await login({ email: "alice@example.com", password: "alice-password" });
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { token: "alice-token" });
});

test("/login: wrong password and unknown email look the same", async () => {
  const wrong = await login({ email: "bob@example.com", password: "nope" });
  const unknown = await login({ email: "nobody@example.com", password: "nope" });
  assert.equal(wrong.status, 401);
  assert.equal(unknown.status, 401);
  assert.deepEqual(await wrong.json(), await unknown.json());
